<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderDisabledAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderDisabledAccessor trait.
 *
 * Covers null default, string/VO assignment via withDisabled,
 * getDisabled/disabled accessors, and isDisabledChanged with/without original.
 */
class TenantLoginProviderDisabledAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDisabled creates a new instance with the Disabled set
     * from a string value, and getDisabled returns the primitive string.
     */
    public function testWithDisabledFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderDisabledAccessorUnitTest();

        // Act
        $result = $holder->withDisabled(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isDisabled());
    }
    /**
     * Asserts that withdisabled has access to the value object
     * from a string value, and getDisabled returns the primitive string.
     */
    public function testWithDisabledFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderDisabledAccessorUnitTest();

        // Act
        $result = $holder->withDisabled(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->disabled()->value());
    }
    public function testChangedDisabled(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderDisabledAccessorUnitTest();
        $original = $holder->withDisabled( true);
        $same = $holder->withDisabled( true);
        $modified = $holder->withDisabled(false);

        // Act
        $unchanged = $holder->isDisabledChanged();
        $withSame = $original->isDisabledChanged( $same );
        $withDiferent = $original->isDisabledChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderDisabledAccessorUnitTest
{
  use TenantLoginProviderDisabledAccessor;
}
